export const isroTimelineData=[{year:1962,mission:"INCOSPAR Established",image:"assets/incospar.jpg",vehicle:"N/A",category:"Foundation",objective:"Establish space research under the Department of Atomic Energy.",outcome:"Laid the foundation for India's space program under the visionary leadership of Dr. Vikram Sarabhai.",achievement:"Birth of India's formal space research efforts.",description:"The Indian National Committee for Space Research (INCOSPAR) was set up, initiating India's space journey."},{year:1969,mission:"ISRO Founded",image:"assets/isro-logo.svg",vehicle:"N/A",category:"Foundation",objective:"Harness space technology for national development.",outcome:"ISRO superseded INCOSPAR, expanding the scope of space research and development.",achievement:"Establishment of the Indian Space Research Organisation.",description:"ISRO was formed on August 15, 1969, with a vision to use space technology for peaceful purposes and national progress."},{year:1975,mission:"Aryabhata",image:"assets/aryabhata.jpg",vehicle:"Kosmos-3M (Soviet Union)",category:"Satellite",objective:"Conduct experiments in X-ray astronomy, aeronomics, and solar physics.",outcome:"Successfully launched with Soviet assistance; provided valuable technological experience.",achievement:"India’s first satellite mission.",description:"Named after the prominent Indian astronomer and mathematician, Aryabhata marked India's entry into the space age."},{year:1980,mission:"SLV-3 & Rohini",image:"assets/slv3.jpg",vehicle:"SLV-3",category:"Launch Vehicle",objective:"Develop an indigenous Satellite Launch Vehicle.",outcome:"Successfully placed the Rohini satellite (RS-1) into orbit.",achievement:"India became the sixth member of the exclusive space club.",description:"The successful launch of SLV-3 proved India's capability to design, build, and launch a satellite launch vehicle."},{year:1994,mission:"PSLV Operational Success",image:"assets/pslv.jpg",vehicle:"PSLV-D2",category:"Launch Vehicle",objective:"Launch IRS class of satellites into Sun Synchronous Orbit.",outcome:"First successful launch of the Polar Satellite Launch Vehicle.",achievement:"Established PSLV as ISRO's reliable workhorse.",description:"The PSLV emerged as a highly versatile and reliable launch vehicle, executing numerous domestic and international missions."},{year:2008,mission:"Chandrayaan-1",image:"assets/chandrayaan1.jpg",vehicle:"PSLV-XL",category:"Lunar Exploration",objective:"Perform chemical, mineralogical, and photo-geologic mapping of the Moon.",outcome:"Confirmed the presence of lunar water molecules.",achievement:"Discovery of evidence of lunar water molecules.",description:"India's first deep space mission, Chandrayaan-1, revolutionized lunar science by detecting water on the Moon."},{year:2013,mission:"Mangalyaan (Mars Orbiter Mission)",image:"assets/mangalyaan.jpg",vehicle:"PSLV-XL",category:"Planetary Science",objective:"Explore Mars' surface features, morphology, mineralogy, and Martian atmosphere.",outcome:"Entered Mars orbit in 2014, operating for over 7 years.",achievement:"First Asian mission to Mars orbit, and first nation to succeed on its maiden attempt.",description:"MOM showcased India's capability to execute a highly cost-effective and complex interplanetary mission."},{year:2019,mission:"Chandrayaan-2",image:"assets/chandrayaan2.jpg",vehicle:"GSLV Mk III",category:"Lunar Exploration",objective:"Soft landing on the lunar surface and deploy a rover.",outcome:"Orbiter highly successful; lander experienced a hard landing.",achievement:"Orbiter continues to provide high-resolution lunar data.",description:"Despite the lander anomaly, the Chandrayaan-2 orbiter remains one of the most advanced lunar orbiters, yielding significant scientific data."},{year:2023,mission:"Chandrayaan-3",image:"assets/chandrayaan3.jpg",vehicle:"LVM3",category:"Lunar Exploration",objective:"Demonstrate safe and soft landing on the lunar surface and rover roving.",outcome:"Historic successful landing near the lunar south pole.",achievement:"First country to land near the lunar south pole.",description:"Chandrayaan-3 achieved a flawless soft landing, deploying the Pragyan rover to conduct in-situ scientific experiments."},{year:2023,mission:"Aditya-L1",image:"assets/aditya-l1.jpg",vehicle:"PSLV-XL",category:"Solar Observation",objective:"Study the solar atmosphere, solar magnetic storms, and their impact on the environment around Earth.",outcome:"Successfully placed in a halo orbit around Lagrange point 1 (L1).",achievement:"India’s first dedicated solar observation mission.",description:"Aditya-L1 continuously observes the Sun to unlock mysteries of solar dynamics and space weather."},{year:"Future",mission:"Gaganyaan",image:"assets/gaganyaan.jpg",vehicle:"HLVM3",category:"Human Spaceflight",objective:"Demonstrate human spaceflight capability to Low Earth Orbit.",outcome:"Extensive testing and preparations ongoing.",achievement:"India's first indigenous crewed orbital spacecraft.",description:"The Gaganyaan program aims to send Indian astronauts to space, marking a new era of human spaceflight for ISRO."}];